package example;
import java.util.concurrent.TimeUnit;
import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;
final class JobRunner {
  private final RedissonClient redis;
  JobRunner(RedissonClient redis) { this.redis = redis; }
  void run(String cacheId, Runnable rebuild) throws InterruptedException {
    RLock lock = redis.getLock("cache:" + cacheId);
    if (!lock.tryLock(2, 10, TimeUnit.SECONDS)) return;
    try { rebuild.run(); }
    finally { lock.unlock(); }
  }
}

